SELECT id, type, temp, humiture, node_id nodeId, gather_site gatherSite, site_type siteType, transfer_time transferTime, alert_level alertLevel, pid_route siteRoute, createdTime, warning_type warningType, humidity_level humidityLevel, temp_level tempLevel FROM tb_air_conditioner_history

    node_id =#{airConditionCode}

order by transfer_time desc limit 1

